D25=[(386817,4741,6950041,172726),(345477,4612,6825968,173242),(291514,3764,6402158,157096),(291000,3673,6493421,156056),(273877,3628,6060734,150506),(266091,3712,6111178,152987),(393377,5993,10274477,247331),(484637,8287,12842685,299475),(538987,9207,13023663,310751),(558957,10041,13802333,325839),(913169,19052,19452493,456251),(686640,15351,15477717,373448),(453080,8505,11865925,292635),(493866,11283,14882608,373231),(551945,15379,16794004,430469),(517153,13022,14742571,370574),(385008,9092,11735125,291023),(357154,7196,10229190,255588),(290917,5045,9249735,215612),(315864,5372,10151489,223191),(415298,7709,13239501,300226),(406784,7507,13553063,289834),(561961,13201,15242022,367348),(421617,7212,12327220,283203),(500634,8068,13195279,295627),(543916,8746,13503346,306978),(979748,18867,20622438,487439),(1320069,23060,29276265,638967),(1389158,25549,29109268,653670),(1106196,19025,23108505,516481)]
S={2024:(264955,3313,6458268,131021),2025:(294741,3334,5915868,146160)}
for y,D in ((2024,D24),(2025,D25)):
    g=sum(r[0] for r in D); im=sum(r[2] for r in D); gv=sum(r[3] for r in D); u=sum(r[1] for r in D)
    ucr=[r[1]/r[3] for r in D]; imv=[r[2] for r in D]
    print(y,'nov gmv',g,'imps',im,'gmv/1k',round(g/im*1000,1),'ucr',round(u/gv*100,2),'corr(imps,ucr)',round(st.correlation(imv,ucr),2), 'corr(imps,gmv)',round(st.correlation(imv,[r[0] for r in D]),2))
    s=S[y]; print('  sep/day ucr',round(s[1]/s[3]*100,2),'gmv/1k',round(s[0]/s[2]*1000,1))
    # split days by imps tercile
    srt=sorted(D,key=lambda r:r[2]); n=len(srt)//3
    for nm,grp in (('low',srt[:n]),('mid',srt[n:2*n]),('high',srt[2*n:])):
        print('  ',nm,'imps/day',round(sum(r[2] for r in grp)/len(grp)/1e6,1),'M ucr',round(sum(r[1] for r in grp)/sum(r[3] for r in grp)*100,2),'ctr',round(sum(r[3] for r in grp)/sum(r[2] for r in grp)*100,2),'gmv/1k',round(sum(r[0] for r in grp)/sum(r[2] for r in grp)*1000,1))
